recipes.code:
{
  "inputs": [
    {
      "id": "lune-api-key",
      "type": "promptString",
      "description": "Lune personal access token. Generate one at https://luneresearch.com/dashboard/credentials.",
      "password": true
    }
  ],
  "servers": {
    "lune": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@retrograde-labs/lune-mcp-server@2.0.0"
      ],
      "env": {
        "LUNE_API_KEY": "${input:lune-api-key}"
      }
    }
  }
}
